# Validate magnitude/phase pairs per echo
for echo_time, group in value.groupby("EchoTime"):
    image_types = group["ImageType"]

    # ImageType is list-valued; check components, not the string repr
    has_magnitude = any("M" in as_list(it) for it in image_types)
    has_phase = any("P" in as_list(it) for it in image_types)

    if not has_magnitude:
        raise ValidationError(f"Echo time {echo_time} ms is missing magnitude image.")

    if not has_phase:
        raise ValidationError(f"Echo time {echo_time} ms is missing phase image.")
